import { attachSaveStatus } from "./save-status.js";
import { createTrailingTask } from "./trailing-task.js";

export function createDraftEditor({ store, timers, renderDocument, renderStatus }) {
  let current = null;
  let navigationRevision = 0;

  function retireCurrent(request) {
    const leaving = current;
    current = null;
    if (leaving) {
      leaving.stop();
      leaving.save.flush();
    }
    if (request === navigationRevision) renderDocument(null);
  }

  function close() {
    const request = ++navigationRevision;
    retireCurrent(request);
  }

  return {
    open(id) {
      const request = ++navigationRevision;
      retireCurrent(request);
      if (request !== navigationRevision) return;

      const visit = {};
      const opened = {
        id,
        text: store.read(id),
        visit,
        save: createTrailingTask((savedId, text) => store.write(savedId, text), 120, timers),
        stop: attachSaveStatus(store, id, renderStatus),
      };
      current = opened;
      renderDocument({ id, text: opened.text });
    },
    edit(text) {
      if (!current) return;
      current.text = text;
      current.save.push(current.id, text);
    },
    selection() {
      return current && { id: current.id, text: current.text, visit: current.visit };
    },
    flush() {
      if (current) current.save.flush();
    },
    isVisitActive(visit) {
      return current !== null && current.visit === visit;
    },
    close,
  };
}

